import{_ as l,C as r,o as t,c as n,a3 as i,b as o,w as e,a as d,E as h,a4 as p}from"./chunks/framework.CWYzGJW1.js";const f=JSON.parse('{"title":"T2 微調實作與部署","description":"一張消費級顯示卡就能用 QLoRA 微調 8B 等級的模型, Unsloth 官方標示的最低顯示記憶體約 6GB.","frontmatter":{"description":"一張消費級顯示卡就能用 QLoRA 微調 8B 等級的模型, Unsloth 官方標示的最低顯示記憶體約 6GB."},"headers":[],"relativePath":"train/t2-finetune.md","filePath":"train/t2-finetune.md","lastUpdated":1793064110000}'),g={name:"train/t2-finetune.md"};function c(k,a,m,F,b,u){const s=r("Mermaid");return t(),n("div",null,[a[1]||(a[1]=i('<h1 id="t2-微調實作與部署" tabindex="-1">T2 微調實作與部署 <a class="header-anchor" href="#t2-微調實作與部署" aria-label="Permalink to &quot;T2 微調實作與部署&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">本章屬性</p><ul><li>等級: ○ 依情境</li><li>狀態: 可閱讀</li><li>資料基準日: 2026-10-27</li><li>實機驗證: 未進行 (指令依官方文件整理; 需實機確認: 各框架實際的顯示記憶體用量與訓練時間, 以及轉檔後的模型能否正常載入)</li></ul></div><p><strong>結論</strong>: 一張消費級顯示卡就能用 QLoRA 微調 8B 等級的模型, Unsloth 官方標示的最低顯示記憶體約 6GB. 微調的完整流程是: 準備資料, 用微調框架訓練出 LoRA 參數, 合併回原模型, 以 llama.cpp 轉成 GGUF 並量化, 再交給 Ollama 或 llama-server 提供服務. 上線前用 <a href="/lanai-handbook/build/m6-observability">M6</a> 的同一份測試集比較微調前後的成績, 並保留原模型, 結果不如預期時可以立即切回.</p><div class="tip custom-block"><p class="custom-block-title">本章常見名詞</p><table tabindex="0"><thead><tr><th>詞</th><th>意思</th></tr></thead><tbody><tr><td>LoRA</td><td>凍結原模型, 只訓練一小組附加的低秩矩陣的微調方法</td></tr><tr><td>QLoRA</td><td>先把原模型量化成 4 位元, 再在上面做 LoRA, 進一步減少顯示記憶體</td></tr><tr><td>adapter</td><td>LoRA 訓練出來的那一小組附加參數, 可以單獨存檔, 也可以合併回原模型</td></tr><tr><td>合併 (merge)</td><td>把 adapter 的參數加回原模型, 得到一個完整的新模型檔</td></tr><tr><td>微調框架</td><td>負責讀取資料, 執行訓練迴圈並輸出 adapter 的軟體, 例如 Unsloth, Axolotl</td></tr><tr><td>GGUF</td><td>llama.cpp 與 Ollama 使用的模型檔格式, 見 <a href="/lanai-handbook/know/k1-basics">K1</a></td></tr><tr><td>量化</td><td>把模型的數字存得粗一點以縮小檔案, 見 <a href="/lanai-handbook/know/k2-quantization">K2</a></td></tr></tbody></table><p>完整詞彙見<a href="/lanai-handbook/ref/glossary">術語對照</a>.</p></div><h2 id="t2-1-lora-與-qlora-原理" tabindex="-1">T2.1 LoRA 與 QLoRA 原理 <a class="header-anchor" href="#t2-1-lora-與-qlora-原理" aria-label="Permalink to &quot;T2.1 LoRA 與 QLoRA 原理&quot;">​</a></h2><p>微調不一定要改動模型的全部參數. 可以想成在原本的教科書上貼便利貼補充, 而不是重印整本書: 書本內容 (原模型) 保持不變, 新學到的東西寫在便利貼 (附加參數) 上, 閱讀時兩者一起看.</p><p>LoRA (Low-Rank Adaptation, 低秩適配) 凍結預訓練模型的權重, 在 Transformer 架構的每一層加入可訓練的低秩分解矩陣, 訓練時只更新這些矩陣. 論文以 GPT-3 175B 為例, 與用 Adam 全參數微調相比, 可訓練參數減少約 1 萬倍, 顯示記憶體需求約降為三分之一; 而且與 adapter 層的做法不同, LoRA 不會增加推論延遲 (來源: Hu 等人, LoRA 論文, 2021). 「低秩」可以理解為用兩個細長的小矩陣相乘, 去近似一個大矩陣的變化量, 所以要訓練的數字少很多.</p><p>QLoRA 進一步把凍結的原模型量化成 4 位元, 梯度穿過這個 4 位元模型, 只更新 LoRA 的參數. 論文提出三項技術: 4 位元 NormalFloat (NF4) 資料型別, 把量化常數再量化一次的雙重量化, 以及處理記憶體尖峰的分頁最佳化器; 作者表示, 這些技術讓單張 48GB 顯示卡就能微調 65B 參數的模型, 並保有 16 位元微調的任務表現 (來源: Dettmers 等人, QLoRA 論文, 2023).</p><p>這兩種方法讓微調從「需要多張資料中心級顯示卡」降到「一張消費級顯示卡」. 各模型大小的顯示記憶體最低值見 <a href="/lanai-handbook/train/t1-decide">T1.3</a>.</p><h2 id="t2-2-微調工具-各自負責什麼" tabindex="-1">T2.2 微調工具: 各自負責什麼 <a class="header-anchor" href="#t2-2-微調工具-各自負責什麼" aria-label="Permalink to &quot;T2.2 微調工具: 各自負責什麼&quot;">​</a></h2><p>微調流程中有三類工具, 各自負責不同的步驟. 可以想成做菜: 微調框架是主廚, 負責把食材 (資料) 和原料 (原模型) 做成新的料理 (adapter); llama.cpp 是包裝線, 負責把成品轉成店裡用的盒子 (GGUF) 並分裝 (量化); 推論引擎是外場, 負責把成品端給客人 (提供 API).</p>',11)),(t(),o(p,null,{default:e(()=>[h(s,{id:"mermaid-126",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E8%A8%93%E7%B7%B4%E8%B3%87%E6%96%99%20JSONL%22%5D%20--%3E%20C%5B%22%E5%BE%AE%E8%AA%BF%E6%A1%86%E6%9E%B6%3A%20Unsloth%2C%20Axolotl%2C%20LLaMA-Factory%20%E6%88%96%20MLX%20LM%20(%E5%9B%9B%E9%81%B8%E4%B8%80)%22%5D%0A%20%20B%5B%22%E5%8E%9F%E6%A8%A1%E5%9E%8B%20(safetensors)%22%5D%20--%3E%20C%0A%20%20C%20--%3E%7C%22%E8%BC%B8%E5%87%BA%20LoRA%20adapter%22%7C%20D%5B%22%E5%90%88%E4%BD%B5%20adapter%20%E8%88%87%E5%8E%9F%E6%A8%A1%E5%9E%8B%20(%E5%A4%9A%E6%95%B8%E6%A1%86%E6%9E%B6%E5%85%A7%E5%BB%BA%E5%90%88%E4%BD%B5%E6%88%96%E5%8C%AF%E5%87%BA%E5%8A%9F%E8%83%BD)%22%5D%0A%20%20D%20--%3E%20E%5B%22llama.cpp%3A%20convert_hf_to_gguf.py%20%E8%BD%89%E6%88%90%20GGUF%2C%20%E5%86%8D%E4%BB%A5%20llama-quantize%20%E9%87%8F%E5%8C%96%22%5D%0A%20%20E%20--%3E%20F%5B%22%E6%8E%A8%E8%AB%96%E5%BC%95%E6%93%8E%3A%20Ollama%20%E6%88%96%20llama-server%20(M1)%20%E8%BC%89%E5%85%A5%E6%96%B0%E6%A8%A1%E5%9E%8B%22%5D%0A%20%20F%20--%3E%20G%5B%22M6%20%E6%B8%AC%E8%A9%A6%E9%9B%86%E6%AF%94%E8%BC%83%E5%BE%AE%E8%AA%BF%E5%89%8D%E5%BE%8C%E7%9A%84%E6%88%90%E7%B8%BE%2C%20%E9%80%9A%E9%81%8E%E6%89%8D%E4%B8%8A%E7%B7%9A%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i(`<p>四個微調框架做的是同一件事, 差別在操作方式與支援的硬體. 讀者只需要選一個:</p><table tabindex="0"><thead><tr><th>工具</th><th>在流程中的角色</th><th>操作方式</th><th>授權</th><th>支援平台 (依官方文件)</th></tr></thead><tbody><tr><td>Unsloth</td><td>以節省顯示記憶體為重點的微調框架, 可直接匯出 GGUF</td><td>Python 程式 (Core); 另有網頁介面 Studio</td><td>Core 為 Apache 2.0; Studio 介面為 AGPL-3.0</td><td>Linux 與 WSL 搭配 NVIDIA 顯示卡; Studio 支援 Windows, macOS; AMD 與 Intel 另有指南</td></tr><tr><td>Axolotl</td><td>以 YAML 設定檔驅動的微調框架, 同一份設定可重複執行</td><td>命令列加 YAML 設定檔</td><td>Apache 2.0</td><td>NVIDIA 顯示卡 (bf16 與 Flash Attention 需 Ampere 以上) 或 AMD 顯示卡</td></tr><tr><td>LLaMA-Factory</td><td>提供網頁介面的微調框架, 可不寫程式完成訓練與匯出</td><td>命令列或網頁介面</td><td>Apache 2.0</td><td>Linux, Windows 搭配 CUDA; 另支援 Ascend NPU 與 AMD ROCm</td></tr><tr><td>MLX LM</td><td>Apple 晶片專用的文字生成與微調套件</td><td>命令列</td><td>MIT</td><td>Apple silicon 的 Mac</td></tr></tbody></table><p><strong>Unsloth</strong> 負責流程中的訓練步驟, 主打以較少的顯示記憶體完成微調. 官方文件列出支援 LoRA, QLoRA, 全參數微調與強化學習等方法, 並可匯出 GGUF 等格式 (來源: Unsloth GitHub 儲存庫). NVIDIA 顯示卡需 CUDA 運算能力 7.0 以上 (例如 RTX 20 系列, T4, A100); 只有 CPU 時不能訓練 (來源: Unsloth 文件 Unsloth Requirements). 程式套件 (Core) 的授權為 Apache 2.0, 但選配的網頁介面 Studio 採 AGPL-3.0; 若打算把 Studio 改作後提供給他人使用, 先依 <a href="/lanai-handbook/know/k4-licenses">K4</a> 檢查 AGPL 的義務 (來源: Unsloth GitHub 儲存庫 License 一節). 安裝程式套件的方式如下 (來源: Unsloth 文件 pip install; 未實機驗證):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#F69D50;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> unsloth</span></span></code></pre></div><p><strong>Axolotl</strong> 同樣負責訓練步驟, 特色是把模型, 資料與訓練參數全部寫在一份 YAML 設定檔中, 前處理, 訓練, 評估, 量化都沿用同一份設定, 方便留存與重做. 支援全參數微調, LoRA, QLoRA 與多種偏好訓練方法; 需要 Python 3.12 以上與 PyTorch 2.13.0 以上 (來源: PyPI axolotl 0.21.0 頁面, 2026-10-16 發布). 安裝與執行範例如下 (來源同上; 未實機驗證):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#F69D50;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> axolotl</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#F69D50;">axolotl</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> train</span><span style="--shiki-light:#D73A49;--shiki-dark:#F47067;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;">設定檔.ym</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">l</span><span style="--shiki-light:#D73A49;--shiki-dark:#F47067;">&gt;</span></span></code></pre></div><p><strong>LLaMA-Factory</strong> 負責訓練與匯出, 特色是網頁介面: 官方文件表示可透過 WebUI 零程式碼微調, 介面分為訓練, 評估與預測, 對話, 匯出四個部分, 匯出時可指定量化等級 (來源: LLaMA-Factory 文件 WebUI). 支援全參數, 凍結部分層, LoRA 與 QLoRA 等方法 (來源: LLaMA-Factory GitHub README). 安裝與啟動網頁介面的方式如下 (來源: LLaMA-Factory 文件 Installation 與 WebUI; 未實機驗證):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#F69D50;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> clone</span><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;"> --depth</span><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;"> 1</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> https://github.com/hiyouga/LlamaFactory.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> LlamaFactory</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#F69D50;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> .</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#F69D50;">llamafactory-cli</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> webui</span></span></code></pre></div><p>合併 LoRA 參數則用 <code>llamafactory-cli export &lt;設定檔&gt;</code> (來源: LLaMA-Factory GitHub README; 未實機驗證).</p><p><strong>MLX LM</strong> 是 Apple 為自家晶片提供的套件, 在 Mac 上同時負責文字生成與微調. 支援 <code>lora</code>, <code>dora</code> 與 <code>full</code> 三種微調方式; 若指定的模型已量化, 訓練時就會使用 QLoRA. 訓練完成後, <code>mlx_lm.fuse</code> 可以把 adapter 合併回模型, 加上 <code>--export-gguf</code> 可直接輸出 GGUF, 但官方註明此功能只支援 Mistral, Mixtral 與 Llama 架構的 fp16 模型 (來源: MLX LM 文件 LORA.md). 安裝訓練所需的套件如下 (來源: MLX LM 文件; 未實機驗證):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#F69D50;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> &quot;mlx-lm[train]&quot;</span></span></code></pre></div><p><strong>如何選擇</strong> (推論, 信心: 中):</p><ul><li>使用 Mac: 選 MLX LM.</li><li>一張 NVIDIA 顯示卡, 希望用網頁介面操作: 選 LLaMA-Factory, 或 Unsloth Studio (留意 AGPL-3.0).</li><li>需要把每次訓練的設定完整留存, 讓別人可以重做: 選 Axolotl.</li><li>顯示記憶體吃緊: 先試 Unsloth.</li></ul><h2 id="t2-3-繁體中文資料集" tabindex="-1">T2.3 繁體中文資料集 <a class="header-anchor" href="#t2-3-繁體中文資料集" aria-label="Permalink to &quot;T2.3 繁體中文資料集&quot;">​</a></h2><p>微調資料最好的來源是自己的業務資料, 因為微調要教的正是自己的格式與規則 (見 <a href="/lanai-handbook/train/t1-decide">T1</a>). 公開資料集可以補充語料, 但要先確認兩件事: 授權是否允許預定用途, 以及資料怎麼產生. 可以想成採購食材: 除了看價格 (授權), 也要看產地 (來源), 來路不明的食材不應進廚房.</p><p>本輪檢視的公開資料如下 (2026-10-27 查詢):</p><table tabindex="0"><thead><tr><th>資料</th><th>發布者</th><th>授權</th><th>適合的用途與限制</th></tr></thead><tbody><tr><td>FineWeb2 的 <code>cmn_Hani</code> 子集</td><td>Hugging Face</td><td>ODC-By 1.0</td><td>網頁文字, 不是問答格式, 適合持續預訓練而非指令微調; 資料卡未區分繁體與簡體; 該子集磁碟大小約 1.48TB, 已做全域去重</td></tr><tr><td>中文維基百科資料庫備份</td><td>Wikimedia 基金會</td><td>GFDL 與 CC BY-SA 4.0</td><td>百科文字, 同樣不是問答格式; 內容繁簡混雜; CC BY-SA 有相同方式分享的要求</td></tr></tbody></table><p>CC BY-SA 的相同方式分享條款是否及於以這類資料訓練出的模型, 公開資料查無定論 (2026-10-27 查詢). 打算對外散布以這類資料訓練的模型時, 請先洽法律顧問; 只在內部使用時, 至少保留資料來源與授權紀錄.</p><p>指令微調用的繁體中文問答資料集, 公開資料查無同時滿足「授權允許商業使用」與「說明回答由哪個模型或哪些人產生」的資料集 (2026-10-27 查詢 Hugging Face 與網路搜尋, 信心: 低, 搜尋範圍有限). 例如台灣團隊發布的 TaiwanChat 對話資料集標示 CC BY-NC 4.0 (不允許商業用途), 資料卡也沒有說明對話如何產生 (來源: TaiwanChat 資料卡). 因此, 指令微調資料建議由自己的業務資料整理, 或由授權允許的模型產生後經人工逐筆審查. 使用任何公開問答資料集前, 請讀資料卡確認授權 (CC BY-NC 這類授權不允許商業用途) 與產生方式; 若回答是由其他模型產生, 也要檢查該模型的授權是否限制用輸出內容訓練其他模型 (推論, 信心: 中).</p><p>實務上較穩妥的做法, 是從內部文件與歷史紀錄整理問答範例, 依 <a href="/lanai-handbook/train/t1-decide">T1.2</a> 的清單檢查品質 (推論, 信心: 中).</p><h2 id="t2-4-驗證-轉檔上線與回退" tabindex="-1">T2.4 驗證, 轉檔上線與回退 <a class="header-anchor" href="#t2-4-驗證-轉檔上線與回退" aria-label="Permalink to &quot;T2.4 驗證, 轉檔上線與回退&quot;">​</a></h2><p>訓練完成不等於可以上線. 上線前要回答三個問題: 新模型有沒有比較好, 能不能在現有推論引擎上跑, 出問題時能不能馬上換回來. 可以想成新產品上市: 先比對樣品與規格 (驗證), 再包裝上架 (轉檔), 同時保留舊產品的庫存 (回退).</p><h3 id="用同一份測試集比較" tabindex="-1">用同一份測試集比較 <a class="header-anchor" href="#用同一份測試集比較" aria-label="Permalink to &quot;用同一份測試集比較&quot;">​</a></h3><p>微調前後使用 <a href="/lanai-handbook/build/m6-observability">M6</a> 的同一份測試集, 在相同的提示與參數下各跑一次, 比較答對率. 兩點要注意 (推論, 信心: 中):</p><ul><li>測試題不能出現在訓練資料中, 否則分數會偏高 (資料汙染).</li><li>除了微調要改善的題目, 也要測一般能力的題目. 微調可能讓模型在新工作上變好, 卻在原本會的事情上變差.</li></ul><h3 id="轉成-gguf-並量化" tabindex="-1">轉成 GGUF 並量化 <a class="header-anchor" href="#轉成-gguf-並量化" aria-label="Permalink to &quot;轉成 GGUF 並量化&quot;">​</a></h3><p>llama.cpp 在這一步負責格式轉換與量化: 它的 <code>convert_hf_to_gguf.py</code> 把 Hugging Face 格式 (safetensors) 的模型轉成 GGUF, <code>llama-quantize</code> 再把 GGUF 量化成較小的檔案. 官方說明, 模型以 16 位元格式發布時, <code>--outtype auto</code> 或省略此參數即可 (來源: llama.cpp 文件 quantize README). 合併後的模型目錄放在本機時, 轉檔與量化的指令如下 (來源同上, 範例中的 <code>--remote</code> 參數改為本機目錄; 未實機驗證):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#F69D50;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> convert_hf_to_gguf.py</span><span style="--shiki-light:#D73A49;--shiki-dark:#F47067;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;">合併後的模型目</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">錄</span><span style="--shiki-light:#D73A49;--shiki-dark:#F47067;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;"> --outfile</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> model-bf16.gguf</span><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;"> --outtype</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> bf16</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#F69D50;">./build/bin/llama-quantize</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> model-bf16.gguf</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> model-Q4_K_M.gguf</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> Q4_K_M</span></span></code></pre></div><p>官方文件提醒, 量化可能帶來準確度損失, 並警告從已量化的檔案再量化一次, 品質會比從 16 位元或 32 位元量化差很多 (來源同上). 因此應保留 16 位元的 GGUF, 每次都從它量化 (推論, 信心: 高).</p><h3 id="接入推論引擎" tabindex="-1">接入推論引擎 <a class="header-anchor" href="#接入推論引擎" aria-label="Permalink to &quot;接入推論引擎&quot;">​</a></h3><p><strong>Ollama</strong>: 在 Modelfile 中以 <code>FROM</code> 指向 GGUF 檔, 再用 <code>ollama create</code> 建立模型. Ollama 匯入 GGUF 時不會量化, 須先用 llama-quantize 完成量化 (來源: Ollama 文件 Importing a model; 未實機驗證):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#768390;"># Modelfile 內容: FROM /path/to/model-Q4_K_M.gguf</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#F69D50;">ollama</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> create</span><span style="--shiki-light:#D73A49;--shiki-dark:#F47067;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;">新模型名</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">稱</span><span style="--shiki-light:#D73A49;--shiki-dark:#F47067;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> Modelfile</span></span></code></pre></div><p><strong>llama-server</strong>: 也可以不合併, 直接載入原模型與 LoRA adapter. llama-server 的 <code>--lora</code> 參數指定 adapter 檔案路徑, 多個 adapter 以逗號分隔 (來源: llama.cpp 文件 server README). adapter 須先轉成 GGUF; llama.cpp 儲存庫提供 <code>convert_lora_to_gguf.py</code> 腳本 (來源: llama.cpp GitHub 儲存庫檔案列表), 官方模型文件另指向轉換 adapter 的線上工具 GGUF-my-LoRA (來源: llama.cpp 文件 models.md). 依該腳本在 b11889 版的原始碼, 必填參數是 adapter 目錄 (內含 PEFT 的 adapter 設定與權重), 另可用 <code>--base</code> 指定基底模型的設定檔目錄 (只需要設定檔, 不需要權重), <code>--outfile</code> 指定輸出檔, <code>--outtype</code> 指定精度 (f32, f16, bf16, q8_0, auto, 預設 f32) (來源: llama.cpp GitHub 儲存庫 convert_lora_to_gguf.py, 2026-10-27 查閱原始碼).</p><h3 id="回退" tabindex="-1">回退 <a class="header-anchor" href="#回退" aria-label="Permalink to &quot;回退&quot;">​</a></h3><p>保留原模型與原本的設定, 新模型用不同的名稱建立, 不覆蓋舊模型. 新模型的檔案依 <a href="/lanai-handbook/build/m3-model-intake">M3</a> 登記雜湊值與版本, 並在登記表註明訓練資料的版本. 上線後若發現問題, 把 <a href="/lanai-handbook/build/m5-gateway-identity">M5</a> 閘道或使用者介面的模型名稱切回原模型即可 (推論, 信心: 中).</p><h2 id="參考來源" tabindex="-1">參考來源 <a class="header-anchor" href="#參考來源" aria-label="Permalink to &quot;參考來源&quot;">​</a></h2><ul><li><strong>LoRA 的做法, 可訓練參數與顯示記憶體的降幅, 無額外推論延遲</strong>: <a href="https://arxiv.org/abs/2106.09685" target="_blank" rel="noreferrer">Hu 等人, LoRA: Low-Rank Adaptation of Large Language Models (arXiv 2106.09685)</a> (2026-10-27 重新擷取摘要核對)</li><li><strong>QLoRA 的 NF4, 雙重量化, 分頁最佳化器, 單張 48GB 顯示卡微調 65B 模型</strong>: <a href="https://arxiv.org/abs/2305.14314" target="_blank" rel="noreferrer">Dettmers 等人, QLoRA: Efficient Finetuning of Quantized LLMs (arXiv 2305.14314)</a> (2026-10-27 重新擷取摘要核對)</li><li><strong>Unsloth 的支援平台與顯示記憶體</strong>: <a href="https://www.unsloth.ai/docs/get-started/fine-tuning-for-beginners/unsloth-requirements" target="_blank" rel="noreferrer">Unsloth 文件: Unsloth Requirements</a>; <strong>安裝</strong>: <a href="https://unsloth.ai/docs/get-started/install/pip-install" target="_blank" rel="noreferrer">Unsloth 文件: pip install</a>; <strong>授權, 訓練方法, 匯出格式</strong>: <a href="https://github.com/unslothai/unsloth" target="_blank" rel="noreferrer">Unsloth GitHub 儲存庫</a></li><li><strong>Axolotl 的授權, 方法, 需求, 安裝, 版本</strong>: <a href="https://pypi.org/p/axolotl" target="_blank" rel="noreferrer">PyPI: axolotl</a> (0.21.0, 2026-10-16)</li><li><strong>LLaMA-Factory 的授權, 方法, 匯出指令</strong>: <a href="https://github.com/hiyouga/LlamaFactory" target="_blank" rel="noreferrer">LLaMA-Factory GitHub 儲存庫</a>; <strong>安裝</strong>: <a href="https://llamafactory.readthedocs.io/en/latest/getting_started/installation.html#installation" target="_blank" rel="noreferrer">LLaMA-Factory 文件: Installation</a>; <strong>網頁介面</strong>: <a href="https://llamafactory.readthedocs.io/en/latest/getting_started/webui.html" target="_blank" rel="noreferrer">LLaMA-Factory 文件: WebUI</a></li><li><strong>MLX LM 的授權與安裝</strong>: <a href="https://github.com/ml-explore/mlx-lm" target="_blank" rel="noreferrer">MLX LM GitHub 儲存庫</a>; <strong>微調方式, 資料格式, 合併與 GGUF 匯出限制</strong>: <a href="https://github.com/ml-explore/mlx-lm/blob/main/mlx_lm/LORA.md" target="_blank" rel="noreferrer">MLX LM 文件: LORA.md</a></li><li><strong>FineWeb2 的授權, cmn_Hani 子集與去重</strong>: <a href="https://huggingface.co/datasets/HuggingFaceFW/fineweb-2" target="_blank" rel="noreferrer">Hugging Face 資料集: HuggingFaceFW/fineweb-2</a></li><li><strong>維基百科資料庫備份的授權</strong>: <a href="https://cdimage.debian.org/mirror/wikimedia.org/dumps/legal.html" target="_blank" rel="noreferrer">Wikimedia dumps: License information (Debian 鏡像站)</a></li><li><strong>TaiwanChat 的授權 (CC BY-NC 4.0)</strong>: <a href="https://huggingface.co/datasets/yentinglin/TaiwanChat/commits/9492a3c3d566eed6d7cc60a95bce6380349ccbb2/README.md" target="_blank" rel="noreferrer">Hugging Face 資料集: yentinglin/TaiwanChat (資料卡)</a></li><li><strong>GGUF 轉檔與量化指令, 量化的品質提醒</strong>: <a href="https://github.com/ggml-org/llama.cpp/blob/master/tools/quantize/README.md" target="_blank" rel="noreferrer">llama.cpp 文件: quantize README</a>; <strong>轉換腳本與 adapter 轉換工具</strong>: <a href="https://github.com/ggml-org/llama.cpp" target="_blank" rel="noreferrer">llama.cpp GitHub 儲存庫</a>, <a href="https://github.com/ggml-org/llama.cpp/blob/master/docs/models.md" target="_blank" rel="noreferrer">llama.cpp 文件: models.md</a>; <strong>llama-server 的 --lora 參數</strong>: <a href="https://github.com/ggml-org/llama.cpp/blob/master/tools/server/README.md" target="_blank" rel="noreferrer">llama.cpp 文件: server README</a></li><li><strong>Ollama 匯入 GGUF 與不在匯入時量化</strong>: <a href="https://docs.ollama.com/import" target="_blank" rel="noreferrer">Ollama 文件: Importing a model</a></li><li><strong>整理者判斷 (推論, 無外部來源)</strong>: 工具選擇建議, 「低秩」的說明方式, 繁體中文指令資料集的查詢結論, 測試集比較的注意事項, 保留 16 位元 GGUF 的做法, 回退方式.</li><li><strong>文中的類比 (教科書上貼便利貼, 做菜的主廚, 包裝線與外場, 採購食材, 新產品上市)</strong>: 整理者所寫, 無外部來源, 不應當作技術定義引用.</li></ul>`,37))])}const E=l(g,[["render",c]]);export{f as __pageData,E as default};
